import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import review from'./legacy-2017-pm5-review.json';
export type Pm5Row=[string,number];export const pm5Rows=(counts:number[])=>counts.flatMap((n,g)=>Array.from({length:n},(_,i)=>[String.fromCharCode(65+g),i+1]as Pm5Row));
/** Direct rank/chunk specification, independent of the literal source interpreter. */
export function pm5Specification(rows:Pm5Row[],capacity:number){const groups=new Map<string,Pm5Row[]>();for(const row of rows){const g=groups.get(row[0])??[];g.push(row);groups.set(row[0],g);}return[...groups.values()].flatMap(g=>Array.from({length:Math.ceil(g.length/capacity)},(_,n)=>g.slice(n*capacity,(n+1)*capacity)));}
export function pm5Literal(rows:Pm5Row[],a:number,b:number){assert(rows.length>0);let page=1,slot=1,current=rows[0][0],flag=0;const cells=new Map<string,Pm5Row>(),events=[0,0,0,0],branches=[new Set<string>(),new Set<string>(),new Set<string>()];for(const record of rows){if(record[0]!==current){branches[0].add('No');branches[1].add(flag===0?'Yes':'No');current=record[0];slot=a;events[0]++;if(flag===0)page++;flag=0;if(slot<1)throw Error('INDEX_BELOW_ONE');if(cells.has(page+':'+slot))throw Error('OVERWRITE');cells.set(page+':'+slot,record);slot++;}else{branches[0].add('Yes');branches[2].add(slot<b?'Yes':'No');events[1]++;if(slot<1)throw Error('INDEX_BELOW_ONE');if(cells.has(page+':'+slot))throw Error('OVERWRITE');cells.set(page+':'+slot,record);if(slot<b){flag=0;slot++;events[3]++;}else{flag=1;slot=a;page++;events[2]++;}}}const pages:Pm5Row[][]=[];for(const p of[...new Set([...cells.keys()].map(k=>Number(k.split(':')[0])))].sort((a,b)=>a-b)){const keys=[...cells.keys()].filter(k=>Number(k.split(':')[0])===p).sort((a,b)=>Number(a.split(':')[1])-Number(b.split(':')[1]));assert.deepEqual(keys.map(k=>Number(k.split(':')[1])),Array.from({length:keys.length},(_,i)=>i+1),'HOLE');pages.push(keys.map(k=>cells.get(k)!));}return{pages,pageVariable:page,events,branches:branches.map(s=>[...s].sort())};}
export function pm5Witness(a:number,b:number,capacity:number){for(let x=1;x<=7;x++)for(let y=1;y<=7;y++)for(let z=1;z<=7;z++){const rows=pm5Rows([x,y,z]),expected=pm5Specification(rows,capacity);try{const actual=pm5Literal(rows,a,b).pages;if(JSON.stringify(actual)!==JSON.stringify(expected))return{counts:[x,y,z],expected,actual};}catch(e){return{counts:[x,y,z],expected,error:String(e)};}}return null;}
const order=['selection-note','title','intro','business-heading','business-list','figure1-lead','figure1','developer-scope','output-heading','output-description-1','figure2','output-description-2','output-description-3','examples-lead','figure3','figure4','preparation-intro','workspace','input-order','figure5','q1','q2-intro','figure6','q2','q3'];
export function inspectLegacy2017Pm5(body:GeneratedBody,index:number){const fixture=review.cases[index];assert(fixture);assert.equal(body.prompt.length,25);assert.equal(body.choices.length,18);assert.equal(body.answerParts?.length,5);const doc=fixture.displayDocument;
 order.forEach((name,i)=>{const expected=doc.paragraphs.find(p=>p.id===name),actual=body.prompt[i];if(!expected){assert.equal(actual.type,'diagram');return;}if('items'in expected){assert.deepEqual(actual,{type:'list',ordered:true,items:expected.items});}else assert.deepEqual(actual,{type:'paragraph',text:('marker'in expected?expected.marker+' ':'')+expected.text});});
 const figures=body.prompt.filter(b=>b.type==='diagram');assert.deepEqual(figures.map(b=>b.caption),doc.figures.map(f=>f.caption));assert.deepEqual(figures.map(b=>b.scene.kind==='source_figure'&&b.scene.profile),['relations','operation','screen','order','flow','testdata'].map(p=>'legacy-2017-pm5-'+p));
 const capText=body.prompt[12];assert(capText.type==='paragraph');const capacity=Number(capText.text.match(/最大([456])件/)?.[1]);assert.equal(capacity,fixture.capacity);assert(figures[3].alt.includes('最大'+capacity+'件'));assert(figures[2].alt.includes('9列全幅で結合した省略帯')&&figures[2].alt.includes('中央に縦3点'));assert(figures[5].alt.includes('見出しセルがなく')&&!figures[5].alt.includes('左上見出しは空白'));
 const counts='ABC'.split('').map(g=>figures[5].alt.split(g+'グループ').length-1);assert.deepEqual(counts,fixture.groupCounts);assert.deepEqual(figures[3].scene.kind==='source_figure'&&figures[3].scene.values,[capacity]);assert.deepEqual(figures[5].scene.kind==='source_figure'&&figures[5].scene.values,[counts[0]===2?1:0]);
 const texts=body.choices.map(c=>{assert.equal(c.length,1);assert(c[0].type==='paragraph');return c[0].text;});assert.deepEqual(texts,doc.groups.flatMap(g=>g.choices));assert.deepEqual(body.answerParts!.map(p=>p.choiceIds.length),[7,7,4,4,3]);assert.deepEqual(body.answerParts![0].choiceIds,body.answerParts![1].choiceIds);assert.equal(body.answerParts!.reduce((s,p)=>s+p.choiceIds.length,0),25);
 const nums=texts.slice(0,7).map(Number),truths:boolean[][]=[];for(const part of[0,1])truths.push(nums.map(n=>pm5Witness(part===0?n:1,part===0?capacity:n,capacity)===null));const run=pm5Literal(pm5Rows(counts),1,capacity);assert.deepEqual(run.pages,pm5Specification(pm5Rows(counts),capacity));truths.push(run.events.map(n=>n===0));truths.push(texts.slice(11,15).map(text=>{const m=/^購買グループ名が([ABC])グループである注文情報を([1-4])件追加した$/.exec(text);assert(m);const next=[...counts];next[m[1].charCodeAt(0)-65]+=Number(m[2]);const outcome=pm5Literal(pm5Rows(next),1,capacity);assert.deepEqual(outcome.pages,pm5Specification(pm5Rows(next),capacity));return outcome.events.every(n=>n>0);}));
 const q3=review.sourceTranscription.groups[3].choices;assert.deepEqual(texts.slice(15),q3);const full=pm5Literal(pm5Rows([counts[0],capacity,counts[2]]),1,capacity);assert(full.events.every(n=>n>0));assert(full.branches.every(b=>b.join(',')==='No,Yes'));assert.notDeepEqual([],pm5Specification(pm5Rows(counts),capacity));truths.push([false,false,true]);const indices=truths.map(t=>{assert.equal(t.filter(Boolean).length,1);return t.indexOf(true);});
 const answers=body.partAnswers!;answers.forEach((answer,i)=>{assert(answer.kind==='choice');assert.equal(answer.choiceId,body.answerParts![i].choiceIds[indices[i]]);});assert(body.explanation.includes('1から始まる'));assert(body.explanation.includes('最大'+capacity+'件'));assert(body.explanation.includes('未書込の次ページ'));return{capacity,counts,indices,truths,referenceCount:truths.flat().length};
}
